// find a free block using the lookahead buffer
lfs_block_t off = lfs->free.off;
lfs_size_t size = lfs->cfg->block_count;

// iterate over the lookahead buffer
for (lfs_size_t i = 0; i < lfs->cfg->lookahead_size * 8; i++) {
    lfs_block_t block = (off + i) % size;

    // check if block is in lookahead buffer
    lfs_size_t pos = i / 32;
    lfs_size_t bit = i % 32;
    if ((lfs->free.buffer[pos] & (1U << bit)) == 0) {
        // found a free block
        *block = block;

        // mark block as used
        lfs->free.buffer[pos] |= (1U << bit);
        lfs->free.ack = 0;

        // update lookahead offset for wear leveling
        lfs->free.off = (block + 1) % size;

        return 0;
    }
}

// lookahead buffer exhausted, need to scan
int err = lfs_fs_rawtraverse(lfs, NULL, NULL, true);
if (err) {
    return err;
}

// check if any blocks are free
if (lfs->free.size == 0) {
    return LFS_ERR_NOSPC;
}

// reset lookahead buffer
lfs->free.off = lfs->free.i;
lfs->free.ack = 0;
std::memset(lfs->free.buffer, 0, lfs->cfg->lookahead_size);

// populate lookahead buffer
for (lfs_block_t i = 0; i < lfs->cfg->lookahead_size * 8; i++) {
    lfs_block_t block = (lfs->free.off + i) % size;

    if (block < lfs->free.size && (lfs->free.buffer[block / 32] & (1U << (block % 32))) == 0) {
        lfs->free.buffer[i / 32] |= (1U << (i % 32));
    }
}

// retry allocation
return lfs_alloc(lfs, block);
// END_CODE

